const action = $input.first().json || {};
const original = $("Set — Normalize Action Input").item.json || {};

let response = action.message || action.response || original.response || "";

const actionName = String(
  action.action || action.next_action || original.next_action || ""
).toUpperCase();

const available =
  action.available === true ||
  String(action.available).toLowerCase() === "true";

const unavailable =
  action.available === false ||
  String(action.available).toLowerCase() === "false";

if (!response && actionName === "CHECK_AVAILABILITY") {
  if (available && Array.isArray(action.slots) && action.slots.length) {
    response = `The requested service is available. Available times: ${action.slots.join(", ")}`;
  } else if (unavailable) {
    response = "Unfortunately, that time is not available.";
  }
}

if (!response && actionName === "BOOK_APPOINTMENT") {
  if (action.success === true || String(action.success).toLowerCase() === "true") {
    response = action.message || "Your appointment has been booked successfully.";
  } else if (action.success === false || String(action.success).toLowerCase() === "false") {
    response = action.message || "Sorry, we could not book your appointment. Please try another time.";
  }
}

if (!response && actionName === "UPDATE_LEAD_CUSTOMER") {
  if (action.success === true || String(action.success).toLowerCase() === "true") {
    response = action.message || "Your details have been updated successfully.";
  }
}

return [{
  json: {
    business: original.business || {},
    customer: original.customer || {},
    lead: original.lead || {},
    conversation: original.conversation || {},
    response,
    intent: original.intent || "",
    next_action: original.next_action || action.next_action || action.action || "OTHER",
    phone_number: original.phone_number || "",
    phone_number_id: original.phone_number_id || "",
    tenant_id: original.tenant_id || original.business?.tenant_id || original.business?.id || "",
    action_result: action
  }
}];

const input = $json;

let ai = input.output ?? input;

if (typeof ai === "string") {
  try {
    ai = JSON.parse(ai);
  } catch {
    ai = {};
  }
}

if (ai.output && typeof ai.output === "object") {
  ai = ai.output;
}

const intent =
  typeof ai.intent === "string"
    ? ai.intent.trim()
    : "OTHER";

const entities =
  ai.entities && typeof ai.entities === "object"
    ? ai.entities
    : {};

const allowed = new Set([
  "CHECK_AVAILABILITY",
  "BOOK_APPOINTMENT",
  "UPDATE_LEAD_CUSTOMER",
  "OTHER"
]);

const candidate =
  typeof ai.next_action === "string"
    ? ai.next_action.trim().toUpperCase()
    : "OTHER";

const next_action = allowed.has(candidate)
  ? candidate
  : "OTHER";

const response =
  typeof ai.response === "string"
    ? ai.response.trim()
    : "I can help with that.";

const confidence = Math.max(
  0,
  Math.min(
    1,
    Number.isFinite(Number(ai.confidence))
      ? Number(ai.confidence)
      : 0
  )
);

const original = $("Set — Normalize AI Input").item.json;

return [{
  json: {
    business: original.business || {},
    customer: original.customer || {},
    lead: original.lead || {},
    conversation: original.conversation || {},
    message: original.message || {},
    business_knowledge: original.business_knowledge || {},

    phone_number:
      original.phone_number ||
      original.message?.phone_number ||
      original.message?.from ||
      "",

    phone_number_id:
      original.phone_number_id ||
      original.message?.phone_number_id ||
      "",

    tenant_id: original.tenant_id || original.business?.tenant_id || original.business?.id || "",
    business_id: original.business_id || original.business?.id || "",
    conversation_history: original.conversation_history || [],

    intent,
    entities,
    next_action,
    response,
    confidence
  }
}];

const envelope = $input.first().json || {};
const input = envelope.data || envelope;
const body = input.body && typeof input.body === 'object' ? input.body : input;
const business = body.business || body.Business || {};

return [{
  json: {
    next_action: body.next_action || body['Next Action'] || 'OTHER',
    business,
    customer: body.customer || body.Customer || {},
    lead: body.lead || body.Lead || {},
    conversation: body.conversation || body.Conversation || {},
    message: body.message || body.Message || {},
    tenant_id: body.tenant_id || business.id || business.tenant_id || ''
  }
}];

const input = $input.first().json || {};

return [{
  json: {
    success: true,
    action: 'OTHER',
    status: 'FALLBACK',
    next_action: 'OTHER',
    message: 'Action received but no specific workflow is configured.',
    business: input.business || {},
    customer: input.customer || {},
    lead: input.lead || {},
    conversation: input.conversation || {},
    tenant_id: input.tenant_id || ''
  }
}];

const input = $input.first().json || {};

const body = input.body && typeof input.body === 'object'
  ? input.body
  : input;

const value = body.entry?.[0]?.changes?.[0]?.value || body.value || body;
const message = value.messages?.[0] || body.message || {};
const contact = value.contacts?.[0] || body.contact || {};

const phone_number_id =
  value.metadata?.phone_number_id ||
  body.phone_number_id ||
  body.phoneNumberId ||
  '';

const phone_number =
  message.from ||
  body.phone_number ||
  body.from ||
  contact.wa_id ||
  '';

let message_text = '';

if (message.text?.body) {
  message_text = message.text.body;
} else if (message.button?.text) {
  message_text = message.button.text;
} else if (message.interactive?.button_reply?.title) {
  message_text = message.interactive.button_reply.title;
} else if (message.interactive?.list_reply?.title) {
  message_text = message.interactive.list_reply.title;
} else if (body.message?.text) {
  message_text = body.message.text;
} else if (typeof body.message === 'string') {
  message_text = body.message;
}

const customer_name =
  contact.profile?.name ||
  body.customer_name ||
  body.name ||
  phone_number ||
  'Customer';

return [{
  json: {
    raw: body,
    phone_number_id,
    phone_number,
    customer_name,
    message: {
      id: message.id || body.message_id || '',
      type: message.type || 'text',
      text: message_text,
      timestamp: message.timestamp || body.timestamp || new Date().toISOString()
    }
  }
}];

const input = $('Normalize Payload').first().json;
const result = $input.first().json || {};

const data = result.message || result;

if (!data.success && !data.tenant_id) {
  throw new Error('Tenant resolution failed');
}

return [{
  json: {
    ...input,
    tenant_id: data.tenant_id,
    business_id: data.business_id,
    resolved_phone_number_id: data.phone_number_id || input.phone_number_id
  }
}];

const tenant = $('Normalize Tenant Result').first().json;

const response = $input.first().json || {};
const result = response.message || response;
const lead = result.lead || {};

if (!lead.id && !lead.lead_id) {
  throw new Error('Find/Create Lead returned no lead');
}

const leadId = lead.id || lead.lead_id;

const conversationId =
  `whatsapp:${tenant.tenant_id}:${tenant.phone_number}`;

return [{
  json: {
    ...tenant,

    lead: {
      ...lead,
      id: leadId
    },

    customer: {
      id: leadId,
      name: lead.name || tenant.customer_name,
      phone: lead.phone || tenant.phone_number,
      email: lead.email || null
    },

    conversation_id: conversationId
  }
}];

const base = $('Build CRM Context').first().json;

const historyResponse = $('Get Conversation History').first().json || {};
const knowledgeResponse = $('Get Business Knowledge').first().json || {};

const history = historyResponse.message || historyResponse;
const knowledge = knowledgeResponse.message || knowledgeResponse;

return [{
  json: {
    business: {
      id: base.business_id,
      tenant_id: base.tenant_id
    },

    customer: base.customer,
    lead: base.lead,

    conversation: {
      id: base.conversation_id,
      conversation_id: base.conversation_id
    },

    conversation_history: history.turns || [],

    message: base.message,

    business_knowledge: knowledge.knowledge || {},

    tenant_id: base.tenant_id,
    business_id: base.business_id,
    phone_number_id: base.phone_number_id,
    phone_number: base.phone_number
  }
}];

