const envelope = $input.first().json || {};
const input = envelope.data || envelope;
const body = input.body && typeof input.body === 'object' ? input.body : input;

const entities = body.Entities || body.entities || {};
const customer = body.Customer || body.customer || {};
const business = body.Business || body.business || {};
const scheduled = String(entities.scheduled_time || body.scheduled_time || '');
const preferred_date = entities.preferred_date || body.preferred_date || (scheduled ? scheduled.substring(0, 10) : '');
const preferred_time = entities.preferred_time || body.preferred_time || (scheduled.includes('T') ? scheduled.split('T')[1].substring(0, 8) : '');

return [{
  json: {
    business,
    customer,
    lead: body.Lead || body.lead || {},
    service: entities.service || body.service || '',
    preferred_date,
    preferred_time,
    duration_minutes: entities.duration_minutes || body.duration_minutes || 30,
    tenant_id: body.tenant_id || business.id || business.tenant_id || '',
    customer_name: customer.name || body.customer_name || '',
    customer_phone: customer.phone || body.customer_phone || '',
    notes: entities.notes || body.notes || ''
  }
}];

const raw = $input.first().json || {};
const input = (raw.message && typeof raw.message === 'object') ? raw.message : raw;
const success = input.success === true;

return [{
  json: {
    success,
    action: 'BOOK_APPOINTMENT',
    status: success ? 'BOOKED' : 'FAILED',
    appointment_id: input.appointment_id || null,
    service: input.service || '',
    scheduled_time: input.scheduled_time || null,
    tenant_id: input.tenant_id || null,
    message: (typeof input.message === 'string' ? input.message : null) || (
      success ? 'Appointment booked successfully.' : 'Appointment booking failed.'
    )
  }
}];

const envelope = $input.first().json || {};
const input = envelope.data || envelope;
const body = input.body && typeof input.body === "object" ? input.body : input;
const business = body.business || body.Business || {};
const customer = body.customer || body.Customer || {};
const lead = body.lead || body.Lead || {};
const entities = body.entities || body.Entities || {};

return [{ json: {
  Business: business,
  Customer: customer,
  Lead: lead,
  Conversation: body.conversation || body.Conversation || {},
  Message: body.message || body.Message || {},
  Entities: entities,
  tenant_id: business.id || business.tenant_id || body.tenant_id || "",
  lead_id: entities.lead_id || lead.id || lead.lead_id || lead.heshly_lead_id || customer.lead_id || customer.id || "",
  full_name: entities.name || entities.full_name || customer.name || lead.name || lead.full_name || customer.phone || "Customer",
  phone: entities.phone || customer.phone || lead.phone || lead.mobile_no || "",
  email: entities.email || customer.email || lead.email || lead.email_id || null
} }];

const raw = $input.first().json || {};
const input = (raw.message && typeof raw.message === 'object') ? raw.message : raw;
const success = input.success === true;
return [{ json: {
  success,
  action: 'UPDATE_LEAD_CUSTOMER',
  status: success ? 'UPDATED' : 'FAILED',
  lead: input.lead || null,
  customer: input.customer || null,
  message: (typeof input.message === 'string' ? input.message : null) || (success ? 'Lead/customer updated successfully.' : 'Lead/customer update failed.')
} }];

